def dparse(s):
 y,m,d=map(int,s.split('-')); d=min(d,calendar.monthrange(y,m)[1]); return datetime.date(y,m,d)
def first_tue(y,m):
 d=datetime.date(y,m,1); return d+datetime.timedelta((1-d.weekday())%7)
def period(d):
 b=first_tue(d.year,d.month)
 if d<b:
  pm=d.month-1 or 12; py=d.year-(d.month==1); b=first_tue(py,pm)
 return b
# exact dedup all fields excluding id
seen=set(); rr=[]
for r in R:
 k=tuple((x,r[x]) for x in r if x!='id')
 if k not in seen: seen.add(k);rr.append(r)
G=collections.defaultdict(list)
for r in rr:G[(r['employee_id'],period(dparse(r['date'])))].append(r)
mis=[]
for (e,p),rows in sorted(G.items()):
 rate=E[e]; cum=0
 for r in sorted(rows,key=lambda r:(dparse(r['date']),float(r['salary_amount']),int(r['id']))):
  cum+=int(r['hours_worked'])
